import { css } from '@emotion/react';

/** Figma: chat message body — Work Sans 16 / 150% / fg default */
export const chatMessageBodyTypography = css`
  font-family: var(--ai-chat-font-family-body);
  font-size: var(--ai-chat-font-size-body-md);
  font-weight: var(--ai-chat-font-weight-regular);
  line-height: var(--ai-chat-line-height-normal);
  letter-spacing: 0;
  color: var(--ai-chat-color-fg-default);
`;
